    "root\u001F0G𞤀𞤲𞤣𞤮𞤪𞤢𞥄\u001E𞤁𞤫𞤲𞤼𞤢𞤤 𞤋𞤥𞤪𞤢𞥄𞤼𞤭 𞤀𞥄𞤪𞤢𞤦𞤵\u001E𞤀𞤬𞤺𞤢𞤲𞤭𞤧𞤼𞤢𞥄𞤲\u001E𞤀𞤲𞤼𞤭𞤺𞤵𞤱𞤢 & 𞤄𞤢𞤪𞤦𞤵𞥅𞤣𞤢\u001E𞤀𞤲𞤺𞤭𞤤𞤢𞥄\u001E𞤀𞤤𞤦𞤢𞤲𞤭𞤴𞤢𞥄\u001E𞤀𞤪𞤥𞤫𞤲𞤭𞤴𞤢𞥄\u001E𞤀𞤲𞤺𞤮𞤤𞤢𞥄\u001E𞤀𞤲𞤼𞤢𞤪𞤼𞤭𞤳𞤢𞥄\u001E𞤀𞤪𞤶𞤢𞤲𞤼𞤭𞤲𞤢𞥄\u001E𞤅𞤢𞤥𞤵𞤱𞤢 𞤀𞤥𞤫𞤪𞤭𞤳𞤭𞤴𞤢𞤲𞤳𞤮\u001E𞤌𞤼𞤭𞤪𞤧𞤢\u001E𞤌𞤧𞤼𞤢𞤪𞤤𞤭𞤴𞤢𞥄\u001E𞤀𞤪𞤵𞤦𞤢𞥄\u001E𞤕𞤵𞤪𞤭𞥅𞤶𞤫 𞤀𞤤𞤢𞤲𞤣\u001E𞤀𞥁𞤫𞤪𞤦𞤢𞤭𞤶𞤢𞥄𞤲\u001E𞤄𞤮𞤧𞤲𞤭𞤴𞤢 & 𞤖𞤫𞤪𞤧𞤫𞤳𞤮𞤾𞤭𞤲𞤢𞥄\u001E𞤄𞤢𞤪𞤦𞤫𞥅𞤣𞤮𞥅𞤧\u001E𞤄𞤢𞤲𞤺𞤭𞤤𞤢𞤣𞤫𞥅𞤧\u001E𞤄𞤫𞤤𞤶𞤭𞤳𞤢𞥄\u001E𞤄𞤵𞤪𞤳𞤭𞤲𞤢 𞤊𞤢𞤧𞤮𞥅\u001E𞤄𞤵𞥅𞤤𞤺𞤢𞤪𞤭𞤴𞤢𞥄\u001E𞤄𞤢𞤸𞤢𞤪𞤢𞤴𞤲\u001E𞤄𞤵𞤪𞤵𞤲𞤣𞤭\u001E𞤄𞤫𞤲𞤫𞤲\u001E𞤅𞤼. 𞤄𞤢𞤪𞤼𞤫𞤤𞤭𞤥𞤭\u001E𞤄𞤭𞤪𞤥𞤵𞤣𞤢\u001E𞤄𞤵𞤪𞤲𞤢𞥄𞤴\u001E𞤄𞤮𞤤𞤭𞥅𞤾𞤭𞤴𞤢𞥄\u001E𞤑𞤢𞤪𞤦𞤭𞤴𞤢𞥄 𞤖𞤮𞤤𞤢𞤲𞤣𞤭𞤴𞤢𞥄\u001E𞤄𞤪𞤢𞤧𞤭𞤤\u001E𞤄𞤢𞤸𞤢𞤥𞤢𞥄𞤧\u001E𞤄𞤵𞥅𞤼𞤢𞥄𞤲\u001E𞤅𞤵𞤪𞤭𞥅𞤪𞤫 𞤄𞤵𞥅𞤾𞤫𞥅\u001E𞤄𞤮𞤼𞤧𞤵𞤱𞤢𞥄𞤲𞤢\u001E𞤄𞤫𞤤𞤢𞤪𞤵𞥅𞤧\u001E𞤄𞤫𞤤𞤭𞥅𞥁\u001E𞤑𞤢𞤲𞤢𞤣𞤢𞥄\u001E𞤕𞤵𞤪𞤭𞥅𞤶𞤫 𞤑𞤮𞤳𞤮𞥅𞤧 (𞤑𞤭𞥅𞤤𞤭𞤲𞤺)\u001E𞤑𞤮𞤲𞤺𞤮 - 𞤑𞤭𞤲𞤧𞤢𞤧𞤢\u001E𞤐𞤣𞤫𞤲𞤣𞤭 𞤚𞤵𞤥𞤦𞤮𞥅𞤪𞤭 𞤀𞤬𞤪𞤭𞤳𞤢𞥄\u001E𞤑𞤮𞤲𞤺𞤮 - 𞤄𞤪𞤢𞥁𞤢𞤾𞤭𞤤\u001E𞤅𞤵𞤱𞤭𞤪𞤧𞤢𞥄\u001E𞤑𞤮𞤼𞤣𞤭𞤾𞤢𞥄𞤪\u001E𞤕𞤵𞤪𞤭𞥅𞤶𞤫 𞤑𞤵𞥅𞤳\u001E𞤕𞤭𞤤𞤫𞥊𞥅\u001E𞤑𞤢𞤥𞤢𞤪𞤵𞥅𞤲\u001E𞤕𞤢𞤴𞤲𞤢\u001E𞤑𞤮𞤤𞤮𞤥𞤦𞤭𞤴𞤢𞥄\u001E𞤑𞤮𞤧𞤼𞤢 𞤈𞤭𞤳𞤢𞥄\u001E𞤑𞤵𞥅𞤦𞤢𞥄\u001E𞤑𞤢𞥄𞤦𞤮 𞤜𞤫𞤪𞤣𞤫\u001E𞤑𞤵𞥅𞤪𞤢𞤧𞤢𞤱𞤮\u001E𞤅𞤵𞤪𞤭𞥅𞤪𞤫 𞤑𞤭𞤪𞤧𞤭𞤥𞤢𞥄𞤧\u001E𞤑𞤵𞤦𞤪𞤵𞥅𞤧\u001E𞤕𞤫𞥅𞤳𞤭𞤴𞤢𞥄\u001E𞤔𞤫𞤪𞤥𞤢𞤲𞤭𞥅\u001E𞤔𞤭𞤦𞤵𞥅𞤼𞤭\u001E𞤁𞤢𞤲𞤵𞤥𞤢𞤪𞤳\u001E𞤁𞤮𞤥𞤭𞤲𞤭𞤳𞤢𞥄\u001E𞤐𞤣𞤫𞤲𞤣𞤭 𞤁𞤮𞤥𞤭𞤲𞤭𞤳𞤢𞥄\u001E𞤀𞤤𞤶𞤢𞤪𞤭𞥅\u001E𞤉𞤳𞤵𞤱𞤢𞤣𞤮𞥅𞤪\u001E𞤉𞤧𞤼𞤮𞤲𞤭𞤴𞤢𞥄\u001E𞤃𞤭𞤧𞤭𞤪𞤢\u001E𞤅𞤢𞥄𞤸𞤢𞤪𞤢 𞤖𞤭𞥅𞤲𞤢𞥄𞤪𞤭\u001E𞤉𞤪𞤭𞥅𞤼𞤫𞤪𞤫\u001E𞤉𞤧𞤨𞤢𞤻𞤢𞥄\u001E𞤀𞤦𞤢𞤧𞤭𞤲𞤭𞥅\u001E𞤊𞤭𞤲𞤤𞤢𞤲𞤣\u001E𞤊𞤭𞤶𞤭𞥅\u001E𞤕𞤵𞤪𞤭𞥅𞤶𞤫 𞤊𞤢𞤤𞤳𞤵𞤤𞤢𞤲𞤣\u001E𞤃𞤭𞤳𞤪𞤮𞤲𞤫𞥅𞤧𞤭𞤴𞤢\u001E𞤕𞤵𞤪𞤭𞥅𞤶𞤫 𞤊𞤢𞤪𞤵𞥅𞤧\u001E𞤊𞤢𞤪𞤢𞤲𞤧𞤭\u001E𞤘𞤢𞤦𞤮𞤲\u001E𞤁𞤫𞤲𞤼𞤢𞤤 𞤐𞤺𞤫𞤯𞤵𞥅𞤪𞤭\u001E𞤘𞤢𞤪𞤲𞤢𞤣𞤢𞥄\u001E𞤔𞤮𞤪𞤶𞤭𞤴𞤢𞥄\u001E𞤘𞤵𞤴𞤢𞥄𞤲 𞤊𞤪𞤢𞤲𞤧𞤭𞤲𞤳𞤮\u001E𞤘𞤢𞤪𞤲𞤫𞤧𞤭𞥅\u001E𞤘𞤢𞤲𞤢\u001E𞤔𞤭𞤦𞤪𞤢𞤤𞤼𞤢𞥄\u001E𞤘𞤭𞤪𞤤𞤢𞤲𞤣𞤭\u001E𞤘𞤢𞤥𞤦𞤭𞤴𞤢\u001E𞤘𞤭𞤲𞤫\u001E𞤘𞤵𞤱𞤢𞤣𞤢𞤤𞤵𞤨𞤫𞥅\u001E𞤘𞤭𞤲𞤫 𞤕𞤢𞤳𞤢𞤲𞤼𞤫𞥅𞤪𞤭\u001E𞤀𞤤𞤴𞤵𞤲𞤢𞥄𞤲\u001E𞤐𞤢𞤲𞥆𞤢𞥄𞤲𞤺𞤫 𞤔𞤮𞤪𞤶𞤭𞤴𞤢 & 𞤕𞤵𞤪𞤭𞥅𞤶𞤫 𞤐𞤢𞤲𞥆𞤢𞥄𞤲𞤺𞤫 𞤅𞤢𞤲𞤣𞤵𞤱𞤭𞥅𞤷\u001E𞤘𞤵𞤱𞤢𞤼𞤫𞤥𞤢𞤤𞤢𞥄\u001E𞤘𞤵𞤱𞤢𞥄𞤥\u001E𞤘𞤭𞤲𞤫-𞤄𞤭𞤧𞤢𞤱𞤮𞥅\u001E𞤘𞤢𞤴𞤢𞤲𞤢𞥄\u001E𞤖𞤂𞤀 𞤕𞤢𞤴𞤲𞤢 𞤫 𞤖𞤮𞤲𞤺 𞤑𞤮𞤲𞤺\u001E𞤕𞤵𞤪𞤭𞥅𞤶𞤫 𞤖𞤭𞤪𞤣𞤭 & 𞤃𞤢𞤳𞤣𞤮𞤲𞤢𞤤\u001E𞤖𞤮𞤲𞤣𞤭𞤪𞤢𞥄𞤧\u001E𞤑𞤵𞤪𞤱𞤢𞥄𞤧𞤭𞤴𞤢\u001E𞤖𞤢𞤴𞤼𞤭𞥅\u001E𞤖𞤢𞤲𞤺𞤢𞤪𞤭𞤴𞤢𞥄\u001E𞤋𞤲𞤣𞤮𞤲𞤭𞥅𞤧𞤴𞤢\u001E𞤋𞤪𞤤𞤢𞤲𞤣\u001E𞤋𞤧𞤪𞤢𞥄𞤴𞤭𞥅𞤤\u001E𞤅𞤵𞤪𞤭𞥅𞤪𞤫 𞤃𞤫𞥅𞤲\u001E𞤋𞤲𞤣𞤭𞤴𞤢\u001E𞤋𞤪𞤢𞥄𞤳\u001E𞤋𞤪𞤢𞥄𞤲\u001E𞤀𞤴𞤧𞤵𞤤𞤢𞤲𞤣\u001E𞤋𞤼𞤢𞤤𞤭𞥅\u001E𞤔𞤫𞤪𞤧𞤭𞥅\u001E𞤔𞤢𞤥𞤢𞤴𞤳𞤢𞥄\u001E𞤔𞤮𞤪𞤣𞤢𞥄𞤲\u001E𞤐𞤭𞤨𞥆𞤮𞤲\u001E𞤑𞤫𞤲𞤭𞤴𞤢𞥄\u001E𞤑𞤭𞤪𞤶𞤭𞤧𞤼𞤢𞥄𞤲\u001E𞤑𞤢𞤥𞤦𞤮𞥅𞤣𞤭𞤴𞤢\u001E𞤑𞤭𞤪𞤦𞤢𞤼𞤭𞥅\u001E𞤑𞤮𞤥𞤮𞥅𞤪𞤮\u001E𞤅𞤼. 𞤑𞤪𞤭𞤧𞤼𞤮𞤦𞤢𞤤 & 𞤐𞤫𞥅𞤾𞤭𞤧\u001E𞤑𞤮𞥅𞤪𞤫𞤴𞤢𞥄 𞤐𞤢𞤲𞥆𞤢𞥄𞤲𞤺𞤫\u001E𞤑𞤮𞥅𞤪𞤫𞤴𞤢𞥄 𞤙𞤢𞤥𞤲𞤢𞥄𞤲𞤺𞤫\u001E𞤑𞤵𞤱𞤢𞤴𞤼𞤵\u001E𞤕𞤵𞤪𞤭𞥅𞤶𞤫 𞤑𞤢𞤴𞤥𞤢𞥄𞤲\u001E𞤑𞤢𞥁𞤢𞤧𞤼𞤢𞥄𞤲\u001E𞤂𞤢𞤱𞤮𞥅𞤧\u001E𞤂𞤭𞤦𞤢𞤲𞤮𞥅𞤲\u001E𞤅𞤼. 𞤂𞤵𞥅𞤧𞤭𞤴𞤢\u001E𞤂𞤭𞤧𞤼𞤫𞤲𞤧𞤭𞤼𞤫𞥅𞤲\u001E𞤅𞤭𞤪 𞤂𞤢𞤲𞤳𞤢𞥄\u001E𞤂𞤢𞤦𞤭𞤪𞤭𞤴𞤢𞥄\u001E𞤂𞤫𞤧𞤮𞤼𞤮𞥅\u001E𞤂𞤭𞤼𞤵𞤾𞤢\u001E𞤂𞤵𞤳𞤧𞤢𞤲𞤦𞤵𞥅𞤺\u001E𞤂𞤢𞤼𞤾𞤭𞤴𞤢\u001E𞤂𞤭𞤦𞤭𞤴𞤢𞥄\u001E𞤃𞤢𞤪𞤮𞥅𞤳\u001E𞤃𞤮𞤲𞤢𞤳𞤮𞥅\u001E𞤃𞤮𞤤𞤣𞤮𞤾𞤢𞥄\u001E𞤃𞤮𞤲𞤼𞤫𞤲𞤫𞥅𞤺𞤮𞤪𞤮\u001E𞤅𞤼. 𞤃𞤢𞤪𞤼𞤫𞤲\u001E𞤃𞤢𞤣𞤢𞤺𞤢𞤧𞤳𞤢𞥄𞤪\u001E𞤅𞤵𞤪𞤭𞥅𞤪𞤫 𞤃𞤢𞤪𞥃𞤢𞤤\u001E𞤃𞤢𞤳𞤫𞤣𞤮𞤲𞤭𞤴𞤢𞥄 𞤐𞤢𞤲𞥆𞤢𞥄𞤲𞤺𞤫\u001E𞤃𞤢𞥄𞤤𞤭\u001E𞤃𞤭𞤴𞤢𞤥𞤢𞥄𞤪 (𞤄𞤵𞥅𞤪𞤥𞤢)\u001E𞤃𞤮𞤲𞤺𞤮𞤤𞤭𞤴𞤢\u001E𞤖𞤂𞤀 𞤕𞤢𞤴𞤲𞤢 𞤫 𞤃𞤢𞤳𞤢𞤱𞤮𞥅\u001E𞤕𞤵𞤪𞤭𞥅𞤶𞤫 𞤃𞤢𞤪𞤭𞤴𞤢𞥄𞤲𞤢 𞤐𞤢𞤲𞥆𞤢𞥄𞤲𞤺𞤫𞥅𞤪𞤭\u001E𞤃𞤢𞤪𞤼𞤭𞤲𞤭𞤳𞤢𞥄\u001E𞤃𞤮𞤪𞤼𞤢𞤲𞤭𞥅\u001E𞤃𞤮𞤲𞤧𞤭𞤪𞤢𞥄𞤼\u001E𞤃𞤢𞤤𞤼𞤢\u001E𞤃𞤮𞤪𞤭𞥅𞤧𞤭\u001E𞤃𞤢𞤤𞤣𞤭𞥅𞤬\u001E𞤃𞤢𞤤𞤢𞤱𞤭𞥅\u001E𞤃𞤫𞤳𞤧𞤭𞤳𞤮𞥅\u001E𞤃𞤢𞤤𞤫𞥅𞤧𞤭𞤴𞤢\u001E𞤃𞤮𞤧𞤢𞤥𞤦𞤭𞥅𞤳\u001E𞤐𞤢𞤥𞤭𞥅𞤦𞤭𞤴𞤢𞥄\u001E𞤑𞤢𞤤𞤭𞤣𞤮𞤲𞤭𞤴𞤢𞥄 𞤖𞤫𞤧𞤮\u001E𞤐𞤭𞥅𞤶𞤫𞤪\u001E𞤅𞤵𞤪𞤭𞥅𞤪𞤫 𞤐𞤮𞤪𞤬𞤮𞤤𞤳𞤵\u001E𞤐𞤢𞤶𞤫𞤪𞤭𞤴𞤢𞥄\u001E𞤐𞤭𞤳𞤢𞤪𞤢𞤺𞤵𞤱𞤢𞥄\u001E𞤖𞤮𞤤𞤢𞤲𞤣𞤭𞤴𞤢𞥄\u001E𞤐𞤮𞤪𞤺𞤫𞤴𞤢𞥄\u001E𞤐𞤭𞤨𞤢𞥄𞤤\u001E𞤐𞤢𞤱𞤪𞤵\u001E𞤐𞤵𞥅𞤱𞤭\u001E𞤐𞤫𞤱 𞤟𞤫𞤤𞤢𞤲𞤣\u001E𞤌𞥅𞤥𞤢𞥄𞤲\u001E𞤆𞤢𞤲𞤢𞤥𞤢\u001E𞤆𞤫𞤪𞤵𞥅\u001E𞤆𞤮𞤤𞤭𞤲𞤫𞥅𞤧𞤭𞤴𞤢 𞤊𞤪𞤢𞤲𞤧𞤭𞤲𞤳𞤮\u001E𞤆𞤢𞤨𞤵𞤱𞤢 𞤘𞤭𞤲𞤫 𞤖𞤫𞤧𞤮\u001E𞤊𞤭𞤤𞤭𞤨𞤭𞥅𞤲\u001E𞤆𞤢𞤳𞤭𞤧𞤼𞤢𞥄𞤲\u001E𞤆𞤮𞤤𞤢𞤲𞤣\u001E𞤅𞤼. 𞤆𞤭𞤴𞤫𞥅𞤪 & 𞤃𞤭𞤳𞤫𞤤𞤮𞤲\u001E𞤕𞤵𞤪𞤭𞥅𞤶𞤫 𞤆𞤭𞤼𞤳𞤭𞥅𞤪𞤲𞤵\u001E𞤆𞤮𞤪𞤼𞤮 𞤈𞤭𞤳𞤮𞥅\u001E𞤂𞤫𞤧𞤣𞤭𞥅𞤶𞤭 𞤊𞤢𞤤𞤫𞤧𞤼𞤭𞥅𞤲\u001E𞤆𞤮𞥅𞤪𞤼𞤵𞤺𞤢𞥄𞤤\u001E𞤆𞤢𞤤𞤢𞤱\u001E𞤆𞤢𞥄𞤪𞤢𞤺𞤵𞤱𞤢𞥄𞤴\u001E𞤊𞤢𞤤𞤫𞤧𞤼𞤭𞥅𞤲\u001E𞤈𞤫𞥅𞤲𞤭𞤴𞤮𞤲\u001E𞤈𞤵𞤥𞤢𞥄𞤲𞤭𞤴𞤢\u001E𞤅𞤫𞤪𞤦𞤭𞤴𞤢𞥄\u001E𞤈𞤮𞥅𞤧𞤭𞤴𞤢\u001E𞤈𞤵𞤱𞤢𞤲𞤣𞤢𞥄\u001E𞤅𞤢𞤵𞥅𞤣 𞤀𞥄𞤪𞤢𞤦𞤭𞤴𞤢𞥄\u001E𞤕𞤵𞤪𞤭𞥅𞤶𞤫 𞤅𞤵𞤤𞤢𞤴𞤥𞤢𞥄𞤲\u001E𞤅𞤫𞤴𞤭𞤧𞤫𞤤\u001E𞤅𞤵𞤣𞤢𞥄𞤲\u001E𞤅𞤵𞤱𞤫𞤣𞤭𞤴𞤢𞥄\u001E𞤅𞤭𞤲𞤺𞤢𞤨𞤵𞥅𞤪\u001E𞤅𞤫𞤲-𞤖𞤫𞤤𞤫𞤲𞤢𞥄\u001E𞤅𞤵𞤤𞤮𞤾𞤫𞤲𞤭𞤴𞤢𞥄\u001E𞤅𞤢𞤾𞤢𞤤𞤦𞤢𞤪𞤣 & 𞤔𞤢𞤲 𞤃𞤢𞤴𞤫𞤲\u001E𞤅𞤵𞤤𞤮𞤾𞤢𞥄𞤳𞤭𞤴𞤢\u001E𞤅𞤢𞤪𞤢𞤤𞤮𞤲\u001E𞤅𞤢𞤲 𞤃𞤢𞤪𞤭𞤲𞤮𞥅\u001E𞤅𞤫𞤲𞤫𞤺𞤢𞥄𞤤\u001E𞤅𞤵𞥅𞤥𞤢𞥄𞤤𞤭\u001E𞤅𞤵𞤪𞤭𞤲𞤢𞥄𞤥\u001E𞤅𞤵𞤣𞤢𞥄𞤲 𞤂𞤫𞤧𞤤𞤫𞤴𞤪𞤭\u001E𞤅𞤢𞤱𞤵 𞤚𞤵𞤥𞤫𞥅 & 𞤆𞤫𞤪𞤫𞤲𞤧𞤭𞤨𞤫\u001E𞤉𞤤 𞤅𞤢𞤤𞤾𞤢𞤣𞤮𞥅𞤪\u001E𞤅𞤫𞤲𞤼𞤵 𞤃𞤢𞥄𞤪𞤼𞤫𞤲\u001E𞤅𞤵𞥅𞤪𞤭𞤴𞤢𞥄\u001E𞤉𞤧𞤱𞤢𞤼𞤭𞤲𞤭\u001E𞤕𞤵𞤪𞤭𞥅𞤶𞤫 𞤚𞤵𞤪𞤳𞤵𞤧 & 𞤑𞤢𞤴𞤳𞤮𞥅𞤧\u001E𞤕𞤢𞥄𞤣\u001E𞤚𞤵𞤥𞤦𞤫 𞤂𞤫𞤧𞤤𞤫𞤴𞤶𞤫 𞤊𞤪𞤢𞤲𞤧𞤭\u001E𞤚𞤮𞤺𞤮\u001E𞤚𞤢𞥄𞤴𞤤𞤢𞤲𞤣\u001E𞤚𞤢𞤶𞤭𞤳𞤭𞤧𞤼𞤢𞥄𞤲\u001E𞤚𞤮𞥅𞤳𞤮𞤤𞤢𞥄𞤱𞤵\u001E𞤚𞤭𞤥𞤮𞥅𞤪 𞤂𞤫𞤧𞤼𞤫\u001E𞤚𞤵𞤪𞤳𞤵𞤥𞤫𞤲𞤭𞤧𞤼𞤢𞥄𞤲\u001E𞤚𞤵𞤲𞤭𞥅𞤧𞤢\u001E𞤚𞤮𞤲𞤺𞤢\u001E𞤚𞤵𞤪𞤳𞤭𞤴𞤢𞥄\u001E𞤚𞤭𞤪𞤲𞤭𞤣𞤢𞥄𞤣 & 𞤚𞤮𞤦𞤢𞤺𞤮𞥅\u001E𞤚𞤵𞥅𞤾𞤢𞤤𞤵\u001E𞤚𞤢𞤴𞤱𞤢𞥄𞤲\u001E𞤚𞤢𞤲𞤧𞤢𞤲𞤭𞥅\u001E𞤓𞤳𞤪𞤫𞥅𞤲𞤭𞤴𞤢\u001E𞤓𞤺𞤢𞤲𞤣𞤢𞥄\u001E𞤕𞤵𞤪𞤭𞥅𞤶𞤫 𞤁𞤢𞥄𞤴𞤭𞥅𞤯𞤫 𞤁𞤂𞤀\u001E𞤁𞤫𞤲𞤼𞤢𞤤 𞤂𞤢𞤪𞤫\u001E𞤒𞤵𞤪𞤺𞤮𞤴\u001E𞤓𞥁𞤦𞤫𞤳𞤭𞤧𞤼𞤢𞥄𞤲\u001E𞤜𞤢𞤼𞤭𞤳𞤢𞥄𞤲\u001E𞤅𞤼. 𞤜𞤭𞤲𞤧𞤢𞤲 & 𞤘𞤭𞤪𞤲𞤢𞤣𞤭𞥅𞤲\u001E𞤜𞤫𞥊𞤲𞤭𞥅𞥁𞤵𞤱𞤫𞤤𞤢𞥄\u001E𞤕𞤵𞤪𞤭𞥅𞤶𞤫 𞤜𞤭𞤪𞤺𞤭𞥅𞤲 𞤄𞤪𞤭𞤼𞤢𞤲𞤭𞤴𞤢𞤲𞤳𞤮𞥅𞤶𞤫\u001E𞤕𞤵𞤪𞤭𞥅𞤶𞤫 𞤜𞤭𞤪𞤺𞤭𞥅𞤲 𞤁𞤂𞤀\u001E𞤜𞤭𞤴𞤫𞤼𞤲𞤢𞥄𞤥\u001E𞤜𞤢𞤲𞤵𞤱𞤢𞥄𞤼𞤵\u001E𞤏𞤢𞤤𞥆𞤭𞥅𞤧 & 𞤊𞤵𞤼𞤵𞤲𞤢\u001E𞤅𞤢𞤥𞤵𞤱𞤢\u001E𞤒𞤢𞤥𞤢𞤲\u001E𞤃𞤢𞤴𞤮𞥅𞤼𞤵\u001E𞤀𞤬𞤪𞤭𞤳𞤢 𞤂𞤫𞤧𞤤𞤫𞤴𞤪𞤭\u001E𞤟𞤢𞤥𞤦𞤭𞤴𞤢\u001E𞤟𞤭𞤥𞤦𞤢𞥄𞤥𞤵𞤴𞤢"

